class Solution:
    def findJudge(self, n: int, trust: list[list[int]]) -> int:
        balance = [0] * (n + 1)
        for a, b in trust:
            balance[a] -= 1
            balance[b] += 1
        for i in range(1, n + 1):
            if balance[i] == n - 1:
                return i
        return -1

